import { route } from "@/lib/plattform/server/route";
import { PlattformFehler } from "@/lib/plattform/fehler";

const EINWILLIGUNG = "Ich bin einverstanden, dass ÖkoInvest meine Angaben zur Bearbeitung der Anfrage verarbeitet (Datenschutzerklärung).";

export const POST = route({ auth: "optional", limit: "anfrage", maxBytes: 48 * 1024 }, async ({ body, backend, ip, nutzer }) => {
  if (body.website) return { ok: true, id: "", vorgang: null }; // Honeypot: still verwerfen
  if (body.einwilligung !== true) throw new PlattformFehler(422, "Bitte bestätigen Sie die Einwilligung zur Datenverarbeitung.");
  const ergebnis = await backend.anfrageAnlegen({
    typ: body.typ,
    kontakt: body.kontakt || {},
    daten: body.daten || {},
    herkunft: body.herkunft || {},
    ip,
    einwilligungText: EINWILLIGUNG,
    nutzer,
  });
  return { ok: true, id: ergebnis.id, vorgang: ergebnis.vorgang };
});
// Serverseitige Prüfung der Kampagnen-Zuordnung (siehe src/lib/herkunft.js).

const KANAELE = ["Anzeige", "Social Media", "E-Mail", "Offline/QR", "Kampagne", "Suchmaschine", "KI-Assistent", "Verweis", "Direkt"];
const VERBOTEN = new Set(["<", ">", '"', "'", "`"]);

/** Steuerzeichen und HTML-relevante Zeichen entfernen, kürzen. */
const text = (v, n) =>
  [...String(v ?? "")]
    .filter((z) => z.codePointAt(0) >= 32 && !VERBOTEN.has(z))
    .join("")
    .trim()
    .slice(0, n);
const pfad = (v) => (/^\/[\w\-/.%~]*$/.test(String(v || "")) ? String(v).slice(0, 200) : "");

/** Liefert Frappe-Felder für die Herkunft oder {} */
export function herkunftFelder(h) {
  if (!h || typeof h !== "object") return {};
  return {
    herkunft_kanal: KANAELE.includes(h.kanal) ? h.kanal : "",
    utm_source: text(h.utm_source, 100),
    utm_medium: text(h.utm_medium, 100),
    utm_campaign: text(h.utm_campaign, 100),
    utm_term: text(h.utm_term, 100),
    utm_content: text(h.utm_content, 100),
    herkunft_referrer: text(h.referrer, 120).replace(/[^a-z0-9.\-]/gi, ""),
    einstiegsseite: pfad(h.einstieg),
  };
}

/** Kompakte Zeile für die Übergangslösung über Kontaktanfragen. */
export function herkunftZeile(h) {
  const f = herkunftFelder(h);
  const teile = [
    f.herkunft_kanal && `Kanal: ${f.herkunft_kanal}`,
    f.utm_source && `Quelle: ${f.utm_source}`,
    f.utm_medium && `Medium: ${f.utm_medium}`,
    f.utm_campaign && `Kampagne: ${f.utm_campaign}`,
    f.herkunft_referrer && `Verweis: ${f.herkunft_referrer}`,
    f.einstiegsseite && `Einstieg: ${f.einstiegsseite}`,
  ].filter(Boolean);
  return teile.length ? `[Herkunft] ${teile.join(" · ")}` : "";
}
// src/lib/herkunft.js
//
// Kampagnen-Zuordnung für Anfragen – bewusst OHNE Cookies und OHNE Browserspeicher:
// Beim ersten Seitenaufruf werden UTM-Parameter, verweisende Domain und Einstiegsseite
// im Arbeitsspeicher der geöffneten Website gehalten (bleibt bei Navigation innerhalb der Seite
// erhalten, endet beim Schließen/Neuladen). Übertragen wird nur zusammen mit einer Anfrage.

let erfasst = null;

const UTM = ["utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content"];
const kurz = (v, n = 100) => String(v || "").replace(/[^\p{L}\p{N} _.\-/:+|]/gu, "").slice(0, n);

function eigeneDomain(host) {
  return /(^|\.)oekoinvest\.(com|at|de|ch)$/.test(host) || host === location.host;
}

/** Einmalig beim ersten Laden aufrufen (HerkunftErfassen in LayoutWrapper). */
export function herkunftErfassen() {
  if (typeof window === "undefined" || erfasst) return;
  const url = new URL(window.location.href);
  const utm = Object.fromEntries(UTM.map((k) => [k, kurz(url.searchParams.get(k))]).filter(([, v]) => v));

  let referrer = "";
  try {
    const r = document.referrer ? new URL(document.referrer) : null;
    if (r && !eigeneDomain(r.host)) referrer = r.host.replace(/^www\./, "");
  } catch {
    /* ungültig */
  }

  // Einmal-Tokens nie übernehmen
  const einstieg = url.pathname.replace(/^\/(scan|fortsetzen)\/.*/, "/$1").slice(0, 200);
  erfasst = { ...utm, referrer, einstieg, zeit: new Date().toISOString() };
}

/** Kanal grob klassifizieren (für Auswertungen). */
function kanal(h) {
  const medium = (h.utm_medium || "").toLowerCase();
  if (h.utm_source || h.utm_medium) {
    if (/cpc|ppc|paid|ads?$/.test(medium)) return "Anzeige";
    if (/social/.test(medium)) return "Social Media";
    if (/mail|newsletter/.test(medium)) return "E-Mail";
    if (/qr|print|flyer|offline/.test(medium)) return "Offline/QR";
    return "Kampagne";
  }
  const r = h.referrer || "";
  if (!r) return "Direkt";
  if (/google\.|bing\.|duckduckgo\.|ecosia\.|yahoo\.|qwant\./.test(r)) return "Suchmaschine";
  if (/chatgpt\.com|openai\.com|perplexity\.ai|claude\.ai|gemini\.google|copilot\.microsoft/.test(r)) return "KI-Assistent";
  if (/facebook\.|instagram\.|linkedin\.|xing\.|t\.co$|x\.com|threads\.net|mastodon|social\.|youtube\./.test(r)) return "Social Media";
  return "Verweis";
}

/** Daten zum Mitsenden mit einer Anfrage. `seite` = aktuelle Seite. */
export function herkunft() {
  if (typeof window === "undefined") return null;
  if (!erfasst) herkunftErfassen();
  const h = erfasst || {};
  return { ...h, kanal: kanal(h), seite: window.location.pathname.replace(/^\/(scan|fortsetzen)\/.*/, "/$1").slice(0, 200) };
}

